async function resolveProviderApiKeyFromEnv(
	provider: string,
): Promise<string | undefined> {
	const envKeys =
		(await Llms.getProviderCollection(provider))?.provider?.env ?? [];
	for (const envKey of envKeys) {
		const value = process.env[envKey]?.trim();
		if (value) {
			return value;
		}
	}
	return undefined;
}

export async function buildConnectorStartRequest(input: {
	options: {
		cwd: string;
		model?: string;
		provider?: string;
		apiKey?: string;
		systemPrompt?: string;
		mode: "act" | "plan";
		enableTools: boolean;
	};
	io: ConnectIo;
	loggerConfig: RuntimeLoggerConfig;
	systemRules: string;
	defaultModel?: string;
}): Promise<ChatStartSessionRequest> {
	const providerSettingsManager = new ProviderSettingsManager();
	const lastUsedProviderSettings =
		providerSettingsManager.getLastUsedProviderSettings({
			isClinePassEnabled: true,
		});
	const provider = normalizeProviderId(
		input.options.provider?.trim() ||
			lastUsedProviderSettings?.provider ||
			"cline",
	);
	let selectedProviderSettings =
		providerSettingsManager.getProviderSettings(provider);
	const persistedApiKey = [REDACTED]
		provider,
		selectedProviderSettings,
	);
	let apiKey =
		[REDACTED] ||
		persistedApiKey ||
		(await resolveProviderApiKeyFromEnv(provider)) ||
		"";

	if (!apiKey && isOAuthProvider(provider)) {
		const oauthResult = await ensureOAuthProviderApiKey({
			providerId: provider,
			currentApiKey: [REDACTED],
			existingSettings: selectedProviderSettings,
			providerSettingsManager,
			io: input.io,
		});
		selectedProviderSettings = oauthResult.selectedProviderSettings;
		apiKey = [REDACTED] ?? "";
	}

	const cwd = input.options.cwd;
	const systemPrompt = await resolveSystemPrompt({
		cwd,
		explicitSystemPrompt: input.options.systemPrompt,
		providerId: provider,
		rules: input.systemRules,
	});
	// Providers without a bundled catalog (e.g. a local Ollama server that has
	// not been queried yet) expose a "default" placeholder instead of a model.
	const providerDefaultModel = (await Llms.getProviderCollection(provider))
		?.provider?.defaultModelId;
	const usableProviderDefault =
		providerDefaultModel && providerDefaultModel !== "default"
			? providerDefaultModel
			: undefined;

	return {
		workspaceRoot: resolveWorkspaceRoot(cwd),
		cwd,
		provider,
		model:
			input.options.model?.trim() ||
			selectedProviderSettings?.model ||
			input.defaultModel ||
			usableProviderDefault ||
			CLINE_DEFAULT_MODEL_ID,
		mode: input.options.mode,
		apiKey,
		systemPrompt,
		logger: input.loggerConfig,
		enableTools: input.options.enableTools,
		autoApproveTools: false,
	};
}

